    /* WHAT A CARD IS, READ FROM ITS CORNER. The kind owns the tag in the
       top-left corner — one colour and one shape each, the same on the hand,
       the big card and the collection — and the rarity owns the rim and the
       price tag. The rarity is the pile's own weight (`w`): what is dealt
       least is worth the most. The ladder is silver, emerald, gold and a
       rainbow epic (`step` is the card's `r-<step>` class: the epic's rim
       and tag band run the rainbow, the canvas draws its pink). */
    var KINDS = {
      peg:   { name: "Peg",   plural: "Pegs",   span: "For the whole round", color: "#ff8a3c" },
      wave:  { name: "Wave",  plural: "Waves",  span: "For one wave",        color: "#5ad8ff" },
      charm: { name: "Charm", plural: "Charms", span: "Stays for the round", color: "#c46bff" },
      meta:  { name: "Trick", plural: "Tricks", span: "Plays with your cards", color: "#e8e2d0" }
    };
    var KIND_KEYS = ["peg", "wave", "charm", "meta"];
    var RARITY = {
      4: { name: "Common",   color: "#c9d0dc", step: 1 },
      3: { name: "Uncommon", color: "#46e07a", step: 2 },
      2: { name: "Rare",     color: "#ffc93c", step: 3 },
      1: { name: "Epic",     color: "#ff4fb3", step: 4 }
    };
